<?php include '../auth/cek_login.php';include '../koneksi.php';$id=(int)($_GET['id']??0);$p=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM pelanggan WHERE id=$id"));if(isset($_POST['update'])){$s=mysqli_prepare($conn,'UPDATE pelanggan SET nik=?,nama=?,alamat=?,no_hp=? WHERE id=?');mysqli_stmt_bind_param($s,'ssssi',$_POST['nik'],$_POST['nama'],$_POST['alamat'],$_POST['no_hp'],$id);mysqli_stmt_execute($s);header('Location: index.php');exit;}?><!doctype html><html><head><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content form-page"><h1>Edit Pelanggan</h1><form method="post"><label>NIK</label><input name="nik" value="<?=htmlspecialchars($p['nik'])?>" required><label>Nama</label><input name="nama" value="<?=htmlspecialchars($p['nama'])?>" required><label>Alamat</label><textarea name="alamat" required><?=htmlspecialchars($p['alamat'])?></textarea><label>No HP</label><input name="no_hp" value="<?=htmlspecialchars($p['no_hp'])?>" required><button name="update">Update</button> <a class="btn-delete" href="index.php">Kembali</a></form></div></body></html>
